import * as THREE from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Apply scene position, rotation, scale
  const sp = config.scenePosition || { x: 0, y: 0, z: 0 };
  group.position.set(sp.x ?? 0, sp.y ?? 0, sp.z ?? 0);
  if (sp.rotationXYZ) {
    group.rotation.set(sp.rotationXYZ[0] ?? 0, sp.rotationXYZ[1] ?? 0, sp.rotationXYZ[2] ?? 0);
  }
  if (sp.scaleXYZ) {
    group.scale.set(sp.scaleXYZ[0] ?? 1, sp.scaleXYZ[1] ?? 1, sp.scaleXYZ[2] ?? 1);
  }

  // Load brushed metal texture
  const texture = ctx.textureLoader.load(
    config.imageUrl || '/prism-assets/chrome/brushed-metal.map.png'
  );
  texture.colorSpace = THREE.SRGBColorSpace;

  // Create plane (512x320 atlas region = 1.6:1 aspect)
  const planeGeo = new THREE.PlaneGeometry(1.6, 1);
  const planeMat = new THREE.MeshBasicNodeMaterial({
    map: texture,
    side: THREE.DoubleSide,
  });
  const plane = new THREE.Mesh(planeGeo, planeMat);
  group.add(plane);

  // Render "Get started" text via MSDF fontAtlas
  if (ctx.fontAtlas) {
    const textMesh = ctx.fontAtlas.createTextMesh({
      text: 'Get started',
      font: 'Lora',
      size: 0.42,
      weight: 400,
      color: new THREE.Color('#16161d'),
      anchorX: 'center',
      anchorY: 'middle',
    });
    textMesh.position.z = 0.01;
    group.add(textMesh);
  }

  // Cleanup handler
  group.userData.cleanup = () => {
    planeGeo.dispose();
    planeMat.dispose();
    texture.dispose();
    gsap.killTweensOf(group);
  };

  // Event handlers (empty for static CTA)
  group.userData.handlers = {};

  return group;
}
